import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import Header from './Header';
import '../Components/Itempageyt.css';
import Footer from './Footer';

const ItemPage = () => {
    const navigate = useNavigate();
    const location = useLocation();

    // Extract the item and type from the location state
    const { item, type } = location.state || {};

    // Declare state hooks at the top level
    const [mainImage, setMainImage] = useState(null);
    const [quantity, setQuantity] = useState(1);
    const [message, setMessage] = useState('');

    // If no item found, return early with "Item not found" message
    if (!item) {
        return <div>Item not found.</div>;
    }

    // Initialize mainImage when item data is available, using useEffect

    const incrementQuantity = () => {
        setQuantity(quantity + 1);
    };

    const decrementQuantity = () => {
        if (quantity > 1) {
            setQuantity(quantity - 1);
        }
    };

    const handleAddToCart = () => {
        setMessage(`🪞🪷 ${quantity} ${item.name} added to cart! 🪷🪕`);
        setTimeout(() => {
            setMessage('');
        }, 3000);
    };

    const subtotal = item.price * quantity;

    return (
        <div className="productful">
            <Header />
            <div className="item-page">
                <div className="image-container">
                    <div className='sub-images-container'>
                        {item.images && item.images.map((image, index) => (
                            <img
                                key={index}
                                src={image}
                                onClick={() => setMainImage(image)}
                                alt={`item-image-${index}`}
                            />
                        ))}
                    </div>

                    <div className='Main-image' data-role="imagemagnifier" data-magnifier-mode="glass">
                        <img src={mainImage} alt={item.name} />
                    </div>
                </div>

                <div className="details-container">
                    <h1 className="Name-of-saree">{item.name}</h1>
                    <h3 className="item-price">₹{item.price}</h3>
                    <h3 className="item-description">{item.description}</h3>
                    <button className="add-to-cart-button" onClick={handleAddToCart}>Add to Cart</button>
                    {message && <div className="popup-message">{message}</div>}

                    {/* Quantity control */}
                    <div className="quantity-control">
                        <button className="quantity-button" onClick={decrementQuantity}>-</button>
                        <span className="quantity">{quantity}</span>
                        <button className="quantity-button" onClick={incrementQuantity}>+</button>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
};

export default ItemPage;
